(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function notas(){const m=$('#notasMain');if(!m)return;$$('.notaPdf',m).forEach(b=>b.remove());const modal=$('#notaPdfModal',m);if(modal)modal.remove();}
function installCard(){if(matchMedia('(display-mode: standalone)').matches||navigator.standalone===true)return;if($('#obrixInstallCompact'))return;const card=document.createElement('div');card.id='obrixInstallCompact';card.innerHTML='<button class="obrixInstallX" type="button" aria-label="Fechar">×</button><div class="obrixInstallText"><b>Instalar OBRIX</b><span>Use no navegador ou adicione à Tela de Início.</span></div><button class="obrixInstallBtn" type="button">Como instalar</button>';document.body.appendChild(card);$('.obrixInstallX',card).onclick=()=>{card.remove();sessionStorage.setItem('obrix-install-dismissed','1')};if(sessionStorage.getItem('obrix-install-dismissed')==='1'){card.remove();return}let deferred=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e},{once:true});$('.obrixInstallBtn',card).onclick=async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;return}const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);alert(ios?'No Safari: toque em Compartilhar e depois em “Adicionar à Tela de Início”. Você também pode continuar usando o OBRIX normalmente no navegador.':'No menu do navegador, escolha “Instalar aplicativo” ou “Adicionar à tela inicial”. Você também pode continuar usando o OBRIX normalmente no navegador.')};}
function apply(){notas();installCard()}
const css=document.createElement('style');css.textContent=`#obrixPrivacyBtn,.obrixPrivacyBar,#notasMain .notaPdf,#notasMain #notaPdfModal{display:none!important}#obrixInstallCompact{position:fixed;left:50%;bottom:72px;transform:translateX(-50%);z-index:99990;width:min(430px,calc(100% - 24px));display:flex;align-items:center;gap:9px;background:var(--ob-card,#fff);color:var(--ob-text,#0f172a);border:1px solid var(--ob-border,#d6dee8);border-radius:14px;padding:9px 10px;box-shadow:0 10px 30px rgba(15,23,42,.18)}.obrixInstallText{min-width:0;flex:1}.obrixInstallText b{display:block;font-size:13px;line-height:1.1}.obrixInstallText span{display:block;font-size:10px;line-height:1.25;color:var(--ob-muted,#64748b);margin-top:3px}.obrixInstallBtn{border:1px solid var(--ob-border,#d6dee8);border-radius:9px;background:var(--ob-inner,#f1f4f7);color:var(--ob-text,#0f172a);padding:9px 10px;font-size:11px;font-weight:900;white-space:nowrap}.obrixInstallX{order:3;width:29px;height:29px;border:1px solid var(--ob-border,#d6dee8);border-radius:9px;background:var(--ob-inner,#f1f4f7);color:var(--ob-text,#0f172a);font-size:20px;line-height:1;padding:0}@media(min-width:760px){#obrixInstallCompact{bottom:18px}}@media(max-width:420px){.obrixInstallText span{max-width:170px}.obrixInstallBtn{padding:8px 9px}}`;document.head.appendChild(css);
sessionStorage.removeItem('obrix-fin-hidden');
let tabBlockUntil=0;
document.addEventListener('pointerdown',e=>{const t=e.target.closest?.('#obrixObrasAprovado .detailTabs [data-tab]');if(!t||t.dataset.tab==='financeiro')return;e.preventDefault();e.stopImmediatePropagation();tabBlockUntil=Date.now()+600;const host=$('#obrixObrasAprovado');if(host)host.dataset.tab=t.dataset.tab;window.OBRIX_OBRAS_MODERNO?.render?.(t.dataset.tab)},true);
document.addEventListener('click',e=>{const t=e.target.closest?.('#obrixObrasAprovado .detailTabs [data-tab]');if(t&&t.dataset.tab!=='financeiro'&&Date.now()<tabBlockUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(apply,450));else setTimeout(apply,450);
})();